In `get_openapi_security_definitions`, we can check if the `security_definition` is for an `oauth2` type. If it is, we can merge the scopes.

Wait, `security_definition` is already a `jsonable_encoder` result, so it's a `dict`.

```python
def get_openapi_security_definitions(
    flat_dependant: Dependant,
) -> Tuple[Dict[str, Any], List[Dict[str, Any]]]:
    security_definitions = {}
    operation_security = []
    for security_requirement in flat_dependant.security_requirements:
        security_definition = jsonable_encoder(
            security_requirement.security_scheme.model,
            by_alias=True,
            exclude_none=True,
        )
        security_name = security_requirement.security_scheme.scheme_name

        if security_name in security_definitions:
            existing_definition = security_definitions[security_name]
            if existing_definition.get("type") == "oauth2" and security_definition.get("type") == "oauth2":
                # Merge scopes for each flow
                existing_flows = existing_definition.get("flows", {})
                new_flows = security_definition.get("flows", {})
                for flow_name, flow_content in new_flows.items():
                    if flow_name in existing_flows:
                        existing_scopes = existing_flows[flow_name].get("scopes", {})
                        new_scopes = flow_content.get("scopes", {})
                        existing_flows[flow_name]["scopes"] = {**existing_scopes, **new_scopes}
                    else:
                        existing_flows[flow_name] = flow_content
            else:
                # If not oauth2 or types differ, we just overwrite (as before)
                security_definitions[security_name] = security_definition
        else:
            security_definitions[security_name] = security_definition

        operation_security.append({security_name: security_requirement.scopes})
    return security_definitions, operation_security
```

